import pandas as pd


def encode_region(train: pd.DataFrame, test: pd.DataFrame) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Replace region with its training churn rate. Unseen regions get the training mean."""
    rates = train.groupby("region")["churned"].mean()
    prior = float(train["churned"].mean())
    return (
        train.assign(region=train["region"].map(rates)),
        test.assign(region=test["region"].map(rates).fillna(prior)),
    )
